import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int a = scanner.nextInt();
        int b = scanner.nextInt();
        int c1 = 0, c2 = 0, c3 = 0;

        for (int i = 6; i > 0; i--) {
            int x = Math.abs(i - a);
            int y = Math.abs(i - b);

            if (x < y) {
                c1++;
            } else if (x > y) {
                c2++;
            } else {
                c3++;
            }
        }
        System.out.println(c1 + " " + c3 + " " + c2);
    }
}

