using namespace std;
#include<algorithm>

int main()
{
    int a, b;
    cin >> a >> b;
    int x, y;
    int c1 = 0, c2 = 0, c3 = 0;

    for (int i = 6; i > 0; i--)
    {
        x = max(i, a) - min(i, a);
        y = max(i, b) - min(i, b);


        if (x < y)
            c1++;
        else{
            if (x>y)
                c2++;
            else c3++;
        }

    }
    cout << c1 << " " << c3 << " " << c2;

}
